// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }
    function testFuzz_property(address recipient, uint256 initialBalance) public {
        vm.assume(recipient != address(0) && recipient != address(c) && recipient.code.length == 0);
        initialBalance = bound(initialBalance, 100, 1000 ether);
        vm.deal(address(c), initialBalance);
        uint256 balanceBefore = address(c).balance;

        vm.prank(recipient);
        c.getFirstWithdrawalBonus(recipient);

        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore - 100);
    }
}
